#!/usr/bin/env python3
import json
import os
from pathlib import Path
from datetime import datetime
import sys

def extract_text(obj, max_depth=2, depth=0):
    """Recursively extract text from nested structures."""
    if depth > max_depth:
        return ""

    if isinstance(obj, str):
        return obj[:100]
    elif isinstance(obj, dict):
        for key in ["content", "message", "text", "body", "title"]:
            if key in obj and isinstance(obj[key], str):
                return obj[key][:100]
        for val in obj.values():
            text = extract_text(val, max_depth, depth + 1)
            if text:
                return text
    elif isinstance(obj, list) and obj:
        for item in obj[:2]:
            text = extract_text(item, max_depth, depth + 1)
            if text:
                return text
    return ""

sessions_dir = "/Users/sa/.claude/projects/-Users-sa-rh-1"
sessions = []

for jsonl_file in sorted(Path(sessions_dir).glob("*.jsonl")):
    session_id = jsonl_file.stem
    file_size_kb = jsonl_file.stat().st_size / 1024
    mod_time = datetime.fromtimestamp(jsonl_file.stat().st_mtime)

    first_summary = ""
    last_summary = ""
    key_topics = set()
    files_touched = set()
    death_cause = "normal"
    total_lines = 0

    try:
        with open(jsonl_file, 'r') as f:
            lines = f.readlines()
            total_lines = len(lines)

        # Read first 100 lines
        first_lines = lines[:100]
        for i, line in enumerate(first_lines):
            if line.strip():
                try:
                    entry = json.loads(line)
                    if i == 0 and not first_summary:
                        first_summary = extract_text(entry)

                    # Extract file references
                    if isinstance(entry, dict):
                        entry_str = json.dumps(entry).lower()
                        if "write" in entry_str or "edit" in entry_str:
                            if "file_path" in json.dumps(entry):
                                key_topics.add("file operations")
                        if "commit" in entry_str:
                            key_topics.add("git/commit")
                        if "bridge" in entry_str or "provider" in entry_str:
                            key_topics.add("LLM bridge")
                        if "agent" in entry_str:
                            key_topics.add("agents")
                        if "memory" in entry_str:
                            key_topics.add("memory")
                except:
                    pass

        # Read last 50 lines
        last_lines = lines[-50:]
        for i, line in enumerate(last_lines):
            if line.strip():
                try:
                    entry = json.loads(line)
                    if i == len(last_lines) - 1 and not last_summary:
                        last_summary = extract_text(entry)

                    entry_str = json.dumps(entry).lower()
                    if "error" in entry_str:
                        death_cause = "error"
                    if "overflow" in entry_str and "context" in entry_str:
                        death_cause = "context overflow"
                except:
                    pass

        sessions.append({
            "id": session_id,
            "date": mod_time.strftime("%Y-%m-%d %H:%M"),
            "size_kb": round(file_size_kb, 1),
            "lines": total_lines,
            "first_summary": first_summary[:100].replace("\n", " ") if first_summary else "(no content)",
            "last_summary": last_summary[:100].replace("\n", " ") if last_summary else "(no content)",
            "topics": sorted(list(key_topics)) if key_topics else ["(none detected)"],
            "death_cause": death_cause
        })
    except Exception as e:
        print(f"Error processing {session_id}: {e}", file=sys.stderr)
        continue

# Sort by modification date
sessions.sort(key=lambda x: x["date"])

# Output markdown
print("# Claude Code Session Catalog")
print()
print(f"**Total Sessions:** {len(sessions)}")
print()

for s in sessions:
    print(f"## Session {s['id'][:8]}... — {s['date']}")
    print(f"- **Size:** {s['size_kb']} KB ({s['lines']} lines)")
    print(f"- **Started with:** {s['first_summary']}")
    print(f"- **Ended with:** {s['last_summary']}")
    print(f"- **Key topics:** {', '.join(s['topics'])}")
    print(f"- **Status:** {s['death_cause']}")
    print()
